contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, uint amount) public payable {
        require(caller != address(0));
        require(amount > 0);

        // Read MinSum (public) and caller's balance/unlockTime via the public Acc getter.
        uint minSum = c.MinSum();
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(caller);

        // Try a Collect from the test contract itself, which has no state; it must not revert.
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (, uint balanceAfter) = c.Acc(caller);

        // Rule 1: Collect must never revert (the guard is a bare if, no require/revert path).
        assert(!reverted);

        // Rule 2: state is only changed when the if-condition is true.
        // If the condition was false, balance remains unchanged.
        if (!(balanceBefore >= minSum && balanceBefore >= amount && block.timestamp > unlockTimeBefore)) {
            assert(balanceAfter == balanceBefore);
        } else {
            // If the condition held, the call tries to send amount; if the inner call succeeded,
            // balance decreased by amount.  Regardless, the balance must not increase.
            assert(balanceAfter <= balanceBefore);
            assert(balanceAfter == balanceBefore || balanceAfter + amount == balanceBefore);
        }
    }

    receive() external payable {}
}

