        // Give the test contract a balance so Collect's transfer can succeed.
        if (address(this).balance >= amount) {
            c.Put{value: amount}(0);
        } else {
            c.Put{value: 0}(0);
        }

        // Read the test contract's own account and MinSum.
        uint minSum = c.MinSum();
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // The deciding call: Collect(amount) from the test contract itself.
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (, uint balanceAfter) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // Rule: Collect never reverts (the guard is a bare if with no revert path).
        assert(!reverted);

        if (balanceBefore >= minSum && balanceBefore >= amount && block.timestamp > unlockTimeBefore) {
            // Condition held: the contract attempted to send `amount` to msg.sender (this test contract).
            // If the transfer succeeded, balance decreased by exactly amount and c's balance decreased.
            // If the transfer failed, state is unchanged.
            assert(balanceAfter == balanceBefore || balanceAfter + amount == balanceBefore);
            assert(cBalAfter == cBalBefore || cBalAfter + amount == cBalBefore);
        } else {
            // Condition failed: the guard skipped the body, so balance and c's balance are unchanged.
            assert(balanceAfter == balanceBefore);
            assert(cBalAfter == cBalBefore);
        }
    }

    receive() external payable {}
}

